  Definition tframe (M : mem) : Prop :=
    cell8 SEGS M (sp' + 2648) ret /\ cell8 SEGS M (sp' + 2640) (bv_unsigned (getr R0 8%bv)) /\ cell8 SEGS M (sp' + 2632) (bv_unsigned (getr R0 9%bv))
    /\ cell8 SEGS M (sp' + 2624) (bv_unsigned (getr R0 18%bv)) /\ cell8 SEGS M (sp' + 2616) (bv_unsigned (getr R0 19%bv)) /\ cell8 SEGS M (sp' + 2608) (bv_unsigned (getr R0 20%bv))
    /\ cell8 SEGS M (sp' + 2600) (bv_unsigned (getr R0 21%bv)) /\ cell8 SEGS M (sp' + 2592) (bv_unsigned (getr R0 22%bv)) /\ cell8 SEGS M (sp' + 2584) (bv_unsigned (getr R0 23%bv))
    /\ cell8 SEGS M (sp' + 2576) (bv_unsigned (getr R0 24%bv)) /\ cell8 SEGS M (sp' + 2568) (bv_unsigned (getr R0 25%bv)) /\ cell8 SEGS M (sp' + 2560) (bv_unsigned (getr R0 26%bv))
    /\ cell8 SEGS M (sp' + 2552) (bv_unsigned (getr R0 27%bv)).

  Record tinv (A : AS MI) (M : mem) (model : Model) : Prop := TINV {
    ti_ainv : ainv MI A M model;
    ti_mstd : mstd model;
    ti_fs : m_fs model = m_fs model0;
    ti_fds : m_fds model = m_fds model0;
    ti_sx : sx_inv ST s M;
    ti_roc : ro_clear Ly.L M;
    ti_osx : forall a, owned MI A a -> ~ sx_region ST a;
    ti_eff : eff MI A0 A M0 M W FJW;
    ti_defw : defined M (sp - LIB_STACK) LIB_STACK;
    ti_frame : tframe M
