  Lemma tinv_store : forall A M model M' (Fw : Z -> Prop),
    tinv A M model -> frame_eq Fw M M' ->
    (forall a, Fw a -> W_of W a /\ ~ (sp' + 2552 <= a < sp)) ->
    (forall a : word, M a <> None -> M' a <> None) ->
